mapper.select:
select mc.ID as COLUMN_ID, mc.MODEL_ID as COLUMN_MODEL_ID, mc.NAME as COLUMN_NAME, mc.CODE as COLUMN_CODE, mc.COLUMN_CATEGORY as COLUMN_COLUMN_CATEGORY, mc.DATA_TYPE as COLUMN_DATA_TYPE, mc.DATA_LENGTH as COLUMN_DATA_LENGTH, mc.DATA_SCALE as COLUMN_DATA_SCALE, mc.PRIMARY_KEY_FLAG as COLUMN_PRIMARY_KEY_FLAG, mc.REQUIRED_FLAG as COLUMN_REQUIRED_FLAG, mc.UNIQUE_FLAG as COLUMN_UNIQUE_FLAG, mc.NAME_FLAG as COLUMN_NAME_FLAG, mc.DEFAULT_VALUE as COLUMN_DEFAULT_VALUE, mc.DICT_TYPE_ID as COLUMN_DICT_TYPE_ID, mc.ENCODING_MODE as COLUMN_ENCODING_MODE, mc.ENCODING_VERSION_ID as COLUMN_ENCODING_VERSION_ID, mc.ENCODING_RULE_CONFIG as COLUMN_ENCODING_RULE_CONFIG, mc.DESCRIPTION as COLUMN_DESCRIPTION, mc.DEL_FLAG as COLUMN_DEL_FLAG, mc.RELATED_MODEL_ID as COLUMN_RELATED_MODEL_ID, related_model.NAME as COLUMN_RELATED_MODEL_NAME, related_model.PROJECT_ID as COLUMN_RELATED_PROJECT_ID, related_model.LAYER_ID as COLUMN_RELATED_LAYER_ID, mc.RELATED_CODE as COLUMN_RELATED_CODE, mc.DISPLAY_CODE as COLUMN_DISPLAY_CODE, mc.NODE_RULE as COLUMN_NODE_RULE, mc.DISPLAY_MODE as COLUMN_DISPLAY_MODE from MODEL_COLUMN mc left join MODEL_BASE related_model on mc.COLUMN_CATEGORY in ('RELATION', 'CLASS') and related_model.ID = mc.RELATED_MODEL_ID and related_model.DEL_FLAG = '0' where mc.DEL_FLAG = '0' and mc.MODEL_ID in
#{modelId}
order by mc.MODEL_ID, mc.ID


where DEL_FLAG = '0' and PARENT_ID in

    #{parentId}

order by PARENT_ID, ID

select.where:
and CODE = #{code}
and NAME like concat(concat('%', #{name}), '%')
and PROJECT_ID = #{projectId}
and RESPONSIBLE_USER_ID = #{responsibleUserId}
and LAYER_ID = #{layerId}
and TYPE = #{type}
and VERSION_ID = #{versionId}
and DESCRIPTION = #{description}
and PARENT_ID = #{parentId}
and DEL_FLAG = '0'
and CREATE_TIME = #{createTime}
